description:
Build and read HTTP status lines (lesson 3.01):

```cpp
struct Status { std::string version; int code; std::string reason; };

std::string reasonFor(int code);
std::string statusLine(int code);
std::optional<Status> parseStatusLine(const std::string& line);
std::string classOf(int code);
```

- **reasonFor**: `OK` for 200, `Created` 201, `No Content` 204, `Moved Permanently` 301, `Found` 302, `Not Modified` 304, `Bad Request` 400, `Unauthorized` 401, `Forbidden` 403, `Not Found` 404, `Method Not Allowed` 405, `Too Many Requests` 429, `Internal Server Error` 500, `Service Unavailable` 503; anything else `Unknown`.
- **statusLine** is `HTTP/1.1 CODE REASON\r\n`.
- **parseStatusLine** reads `VERSION CODE REASON` (the reason may contain spaces, or be empty after the second space), where the version starts with `HTTP/`, and the code is exactly three digits from 100 to 599. A trailing `\r\n` or `\r` is ignored.
- **classOf**: `informational` (1xx), `success`, `redirect`, `client error`, `server error`, or `invalid` outside 100 to 599.

starter.solution.cpp:
#include <optional>
#include <string>

struct Status { std::string version; int code; std::string reason; };

std::string reasonFor(int code) { return ""; }
std::string statusLine(int code) { return ""; }
std::optional<Status> parseStatusLine(const std::string& line) { return std::nullopt; }
std::string classOf(int code) { return ""; }

solution.solution.cpp:
#include <cctype>
#include <optional>
#include <string>

struct Status { std::string version; int code; std::string reason; };

std::string reasonFor(int code)
{
    switch (code)
    {
    case 200: return "OK";
    case 201: return "Created";
    case 204: return "No Content";
    case 301: return "Moved Permanently";
    case 302: return "Found";
    case 304: return "Not Modified";
    case 400: return "Bad Request";
    case 401: return "Unauthorized";
    case 403: return "Forbidden";
    case 404: return "Not Found";
    case 405: return "Method Not Allowed";
    case 429: return "Too Many Requests";
    case 500: return "Internal Server Error";
    case 503: return "Service Unavailable";
    default: return "Unknown";
    }
}

std::string statusLine(int code) { return "HTTP/1.1 " + std::to_string(code) + " " + reasonFor(code) + "\r\n"; }

std::optional<Status> parseStatusLine(const std::string& raw)
{
    std::string line{ raw };
    if (line.size() >= 2 && line.compare(line.size() - 2, 2, "\r\n") == 0) line.erase(line.size() - 2);
    else if (!line.empty() && line.back() == '\r') line.pop_back();
    const std::size_t a{ line.find(' ') };
    if (a == std::string::npos) return std::nullopt;
    const std::string version{ line.substr(0, a) };
    if (version.rfind("HTTP/", 0) != 0) return std::nullopt;
    const std::size_t b{ line.find(' ', a + 1) };
    const std::string code{ line.substr(a + 1, b == std::string::npos ? std::string::npos : b - a - 1) };
    if (code.size() != 3) return std::nullopt;
    for (char c : code) if (!std::isdigit(static_cast<unsigned char>(c))) return std::nullopt;
    const int value{ std::stoi(code) };
    if (value < 100 || value > 599) return std::nullopt;
    return Status{ version, value, b == std::string::npos ? "" : line.substr(b + 1) };
}

std::string classOf(int code)
{
    if (code < 100 || code > 599) return "invalid";
    static const char* const names[]{ "informational", "success", "redirect", "client error", "server error" };
    return names[code / 100 - 1];
}

unitTests:
TEST("building status lines") {
    CHECK_EQ(statusLine(200), std::string("HTTP/1.1 200 OK\r\n"));
    CHECK_EQ(statusLine(404), std::string("HTTP/1.1 404 Not Found\r\n"));
    CHECK_EQ(statusLine(418), std::string("HTTP/1.1 418 Unknown\r\n"));
}
TEST("parsing status lines") {
    const auto s{ parseStatusLine("HTTP/1.1 503 Service Unavailable\r\n") };
    CHECK(s.has_value());
    if (s) { CHECK_EQ(s->version, std::string("HTTP/1.1")); CHECK_EQ(s->code, 503); CHECK_EQ(s->reason, std::string("Service Unavailable")); }
    const auto bare{ parseStatusLine("HTTP/1.0 204") };
    if (bare) CHECK_EQ(bare->reason, std::string(""));
    CHECK(bare.has_value());
    for (const char* bad : { "HTTP/1.1 20 OK", "HTTP/1.1 2000 OK", "HTTP/1.1 abc OK", "FTP/1.0 200 OK", "HTTP/1.1 600 Odd", "200 OK", "" })
        CHECK(!parseStatusLine(bad).has_value());
}
TEST("classes") {
    CHECK_EQ(classOf(101), std::string("informational"));
    CHECK_EQ(classOf(204), std::string("success"));
    CHECK_EQ(classOf(304), std::string("redirect"));
    CHECK_EQ(classOf(418), std::string("client error"));
    CHECK_EQ(classOf(599), std::string("server error"));
    CHECK_EQ(classOf(99), std::string("invalid"));
    CHECK_EQ(classOf(600), std::string("invalid"));
}

